export class Counter {
  constructor(start) {
    this.value = start;
  }

  bump(step) {
    this.value += step;
    return this.value;
  }
}

// An unrelated class, so `instanceof` has a NEGATIVE arm whose operands
// are both realm values.
export class Marker {}

// One object carries the method, its twin leaves the slot undefined: the
// two arms of `hooks.ready?.()`.
export const armed = { label: "armed", ready: () => "go" };
export const idle = { label: "idle" };

// A RegExp ARGUMENT: the realm receives a real RegExp rebuilt from the
// host value's source and flags, and reports what it actually got.
export function describeRegExp(re, probe) {
  return [re instanceof RegExp, re.source, re.flags, re.test(probe)].join(":");
}
